//! Encodes protocol values into their wire-format byte representation.

const std = @import("std");
const types = @import("types.zig");

/// Serializes values and retains generated bytes in an arena until reset or deinit.
pub const Deserializer = struct {
    /// Owns the temporary output allocations produced by this encoder.
    arena: std.heap.ArenaAllocator,

    /// Initializes output storage that is reclaimed with this instance.
    pub fn init(allocator: std.mem.Allocator) Deserializer {
        return .{ .arena = .init(allocator) };
    }

    /// Releases the arena and every output buffer allocated from it.
    pub fn deinit(self: *Deserializer) void {
        self.arena.deinit();
    }

    /// Discards prior output while retaining arena capacity for reuse.
    pub fn reset(self: *Deserializer) void {
        _ = self.arena.reset(.retain_capacity);
    }

    /// Encodes one value; the returned slice is borrowed until reset or deinit.
    pub fn process(self: *Deserializer, input: types.ZType) anyerror![]const u8 {
        var output = std.array_list.Managed(u8).init(self.arena.allocator());
        try write(&output, input);
        return output.items;
    }

    /// Calculates the encoded byte length without allocating response storage.
    pub fn encodedLen(input: types.ZType) anyerror!usize {
        return switch (input) {
            .str => |text| addLengths(&.{ 5 + decimalLength(text.len), text.len }),
            .sstr => |text| addLengths(&.{ 1, text.len, 2 }),
            .int => |value| decimalLengthSigned(value) + 3,
            .float => |value| blk: {
                var buffer: [128]u8 = undefined;
                const text = try std.fmt.bufPrint(&buffer, ",{d}\r\n", .{value});
                break :blk text.len;
            },
            .bool => 4,
            .null => 3,
            .array => |array| blk: {
                var total = try addLengths(&.{3 + decimalLength(array.items.len)});
                for (array.items) |item| total = try std.math.add(usize, total, try encodedLen(item));
                break :blk total;
            },
            .map => |map| blk: {
                var total = try addLengths(&.{3 + decimalLength(map.count())});
                var iterator = map.iterator();
                while (iterator.next()) |entry| {
                    total = try std.math.add(usize, total, try encodedLen(.{ .str = entry.key_ptr.* }));
                    total = try std.math.add(usize, total, try encodedLen(entry.value_ptr.*));
                }
                break :blk total;
            },
            .set => |set| blk: {
                var total = try addLengths(&.{3 + decimalLength(set.count())});
                var iterator = set.iterator();
                while (iterator.next()) |entry|
                    total = try std.math.add(usize, total, try encodedLen(entry.key_ptr.*));
                break :blk total;
            },
            .uset => |set| blk: {
                var total = try addLengths(&.{3 + decimalLength(set.count())});
                var iterator = set.iterator();
                while (iterator.next()) |entry| total = try std.math.add(usize, total, try encodedLen(entry.*));
                break :blk total;
            },
            else => error.UnsuportedType,
        };
    }

    fn addLengths(lengths: []const usize) !usize {
        var total: usize = 0;
        for (lengths) |length| total = try std.math.add(usize, total, length);
        return total;
    }

    fn decimalLength(value: usize) usize {
        var length: usize = 1;
        var current = value;
        while (current >= 10) : (current /= 10) length += 1;
        return length;
    }

    fn decimalLengthSigned(value: i64) usize {
        const length = @as(usize, @intFromBool(value < 0));
        var current: u64 = if (value < 0) @as(u64, @bitCast(-(value + 1))) + 1 else @intCast(value);
        var digits: usize = 1;
        while (current >= 10) : (current /= 10) digits += 1;
        return length + digits;
    }

    /// Writes an array header followed by each element's encoding.
    pub fn writeArray(output: *std.array_list.Managed(u8), items: []const types.ZType) anyerror!void {
        try output.print("*{d}\r\n", .{items.len});
        for (items) |item| try write(output, item);
    }

    /// Appends the wire representation of a supported value to `output`.
    /// Returns `UnsuportedType` for values that have no protocol encoding.
    pub fn write(output: *std.array_list.Managed(u8), input: types.ZType) anyerror!void {
        switch (input) {
            .str => |text| {
                try output.print("${d}\r\n", .{text.len});
                try output.appendSlice(text);
                try output.appendSlice("\r\n");
            },
            .sstr => |text| {
                try output.append('+');
                try output.appendSlice(text);
                try output.appendSlice("\r\n");
            },
            .int => |value| try output.print(":{d}\r\n", .{value}),
            .float => |value| try output.print(",{d}\r\n", .{value}),
            .bool => |value| try output.appendSlice(if (value) "#t\r\n" else "#f\r\n"),
            .null => try output.appendSlice("_\r\n"),
            .array => |array| try writeArray(output, array.items),
            .map => |map| {
                try output.print("%{d}\r\n", .{map.count()});
                var iterator = map.iterator();
                while (iterator.next()) |entry| {
                    try write(output, .{ .str = entry.key_ptr.* });
                    try write(output, entry.value_ptr.*);
                }
            },
            .set => |set| {
                try output.print("/{d}\r\n", .{set.count()});
                var iterator = set.iterator();
                while (iterator.next()) |entry| try write(output, entry.key_ptr.*);
            },
            .uset => |set| {
                try output.print("~{d}\r\n", .{set.count()});
                var iterator = set.iterator();
                while (iterator.next()) |entry| try write(output, entry.*);
            },
            else => return error.UnsuportedType,
        }
    }
};
